[{"order":1,"type":"heading","text":"Authentication and Authorization in Flask"},{"order":2,"type":"paragraph","text":"Securing web applications is a fundamental requirement for any backend developer. In this tutorial, we will explore how to implement user authentication (verifying who the user is) and authorization (verifying what the user can do) in a Flask application using Flask-Login and Werkzeug security utilities."},{"order":3,"type":"subheading","text":"Prerequisites and Installation"},{"order":4,"type":"paragraph","text":"Before we begin, ensure you have Python installed. You will need to install Flask, Flask-SQLAlchemy for database management, and Flask-Login for session management. Run the following command in your terminal:"},{"order":5,"type":"code","text":"pip install Flask Flask-SQLAlchemy Flask-Login"},{"order":6,"type":"subheading","text":"Setting Up the Application and Database"},{"order":7,"type":"paragraph","text":"We will start by creating a basic Flask application, configuring a SQLite database, and defining our User model. The User model must inherit from UserMixin provided by Flask-Login to integrate seamlessly with the session manager."},{"order":8,"type":"code","text":"from flask import Flask
from flask_sqlalchemy import SQLAlchemy
from flask_login import UserMixin

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-super-secret-key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(150), unique=True, nullable=False)
    password_hash = db.Column(db.String(150), nullable=False)
    role = db.Column(db.String(50), nullable=False, default='user')"},{"order":9,"type":"subheading","text":"Initializing Flask-Login"},{"order":10,"type":"paragraph","text":"Next, we need to set up the LoginManager instance and define a user_loader function. This function tells Flask-Login how to fetch a specific user from the database using the user ID stored in the session."},{"order":11,"type":"code","text":"from flask_login import LoginManager

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'login'

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))"},{"order":12,"type":"subheading","text":"Implementing Authentication (Register and Login)"},{"order":13,"type":"paragraph","text":"Authentication requires securely hashing passwords during registration and validating them during login. We will use Werkzeug's generate_password_hash and check_password_hash functions."},{"order":14,"type":"code","text":"from flask import render_template, redirect, url_for, request, flash
from werkzeug.security import generate_password_hash, check_password_hash
from flask_login import login_user, logout_user, login_required

@app.route('/register', methods=['POST'])
def register():
    username = request.form.get('username')
    password = request.form.get('password')
    hashed_password = generate_password_hash(password, method='sha256')

    new_user = User(username=username, password_hash=hashed_password, role='user')
    db.session.add(new_user)
    db.session.commit()
    return redirect(url_for('login'))

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')
    user = User.query.filter_by(username=username).first()

    if user and check_password_hash(user.password_hash, password):
        login_user(user)
        return redirect(url_for('dashboard'))

    flash('Invalid credentials')
    return redirect(url_for('login'))"},{"order":15,"type":"subheading","text":"Implementing Authorization"},{"order":16,"type":"paragraph","text":"While authentication ensures the user is logged in, authorization ensures they have the correct permissions to access specific routes. We can use the login_required decorator for general protection and write a custom decorator for role-based authorization."},{"order":17,"type":"code","text":"from functools import wraps
from flask import abort

def admin_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if not current_user.is_authenticated or current_user.role != 'admin':
            abort(403)
        return f(*args, **kwargs)
    return decorated_function

@app.route('/admin')
@login_required
@admin_required
def admin_panel():
    return 'Welcome to the Admin Panel!'"},{"order":18,"type":"subheading","text":"Summary of Best Practices"},{"order":19,"type":"bullet_point","text":"Always use strong password hashing algorithms like Werkzeug's default or bcrypt."},{"order":20,"type":"bullet_point","text":"Never store plain-text passwords in your database."},{"order":21,"type":"bullet_point","text":"Protect sensitive endpoints using both @login_required and custom role decorators."},{"order":22,"type":"bullet_point","text":"Keep your SECRET_KEY safe using environment variables rather than hardcoding it."}]
